<?php $bid=\Chengyu\Core\Input::integer($_GET['edit']??0);$edit=$bid?$a->db->one('SELECT * FROM cy_badges WHERE id=?',[$bid]):null;if($bid&&!$edit){throw new \Chengyu\Core\Problem('Badge not found.',404);}$badgeRows=$a->db->all('SELECT * FROM cy_badges ORDER BY sort_order,id LIMIT 200');$choices=[];foreach($badgeRows as $row){$choices[$row['id']]=$row['name'];} ?>
<section class="page-hero"><div><span class="eyebrow">RECOGNIZE GOOD CONTRIBUTIONS</span><h1><?= t('Community badges') ?></h1><p><?= t('Create, grant, expire or revoke recognition without changing access rights.') ?></p></div><a class="btn secondary" href="<?= e(url('badges')) ?>"><?= t('Open badge gallery') ?><?= icon('arrow') ?></a></section>
<div class="two-column section"><section class="panel glass"><h2><?= t($edit?'Edit badge':'Create a badge') ?></h2><?= form_start('admin_badge').hidden('id',$bid) ?><?php field('name','Badge name',$edit['name']??'','text',['required'=>'required','maxlength'=>'100']);field('description','Description',$edit['description']??'','textarea',['maxlength'=>'1000']);select_field('symbol','Badge symbol',options(\Chengyu\Services\Badges::SYMBOLS),$edit['symbol']??'sparkles');select_field('tone','Visual theme',options(\Chengyu\Services\Badges::TONES),$edit['tone']??'tide');field('sort_order','Sort order',$edit['sort_order']??0,'number',['min'=>'0','max'=>'9999']);check_field('active','Enabled',!$edit || (bool)$edit['active']);button('Save badge','full','check'); ?></form></section><section class="panel"><h2><?= t('Grant recognition') ?></h2><?= form_start('admin_badge_grant') ?><?php field('user_id','User ID','','number',['min'=>'1','required'=>'required']);select_field('badge_id','Community badge',$choices);field('expires_at','Expires at (empty = no expiry)','','datetime-local');button('Grant or update badge','secondary full','gift'); ?></form><p class="hint"><?= t('The same badge is stored once per user. Updating its expiry does not create duplicates.') ?></p><a class="text-link" href="<?= e(au('users')) ?>"><?= t('Find a member') ?><?= icon('arrow') ?></a></section></div>
<div class="recognition-gallery section"><?php foreach($badgeRows as $badge): ?><article class="recognition-card panel" data-badge-tone="<?= e($badge['tone']) ?>"><span class="recognition-medallion"><?= icon($badge['symbol']) ?></span><h3><?= e($badge['name']) ?></h3><p><?= e($badge['description']) ?></p><span class="pill"><?= t($badge['active']?'Enabled':'Disabled') ?></span><a class="text-link" href="<?= e(au('badges',['edit'=>$badge['id']])) ?>"><?= t('Edit badge') ?><?= icon('edit') ?></a></article><?php endforeach ?></div>
<section class="panel"><h2><?= t('Recent grants') ?></h2><?php $grants=$a->db->all('SELECT g.*,b.name,u.display_name FROM cy_user_badges g JOIN cy_badges b ON b.id=g.badge_id JOIN cy_users u ON u.id=g.user_id ORDER BY g.granted_at DESC,g.id DESC LIMIT 30');foreach($grants as $grant): ?><div class="security-event"><div class="grow"><strong><?= e($grant['display_name']) ?> / <?= e($grant['name']) ?></strong><p class="hint">#<?= (int)$grant['user_id'] ?> / <?= $grant['expires_at']?dt((int)$grant['expires_at']):t('No expiry') ?></p></div><?= form_start('admin_badge_revoke').hidden('user_id',$grant['user_id']).hidden('badge_id',$grant['badge_id']) ?><?php button('Revoke','ghost small','close'); ?></form></div><?php endforeach ?><details><summary><?= t('Revoke by member and badge') ?></summary><?= form_start('admin_badge_revoke') ?><?php field('user_id','User ID','','number',['min'=>'1','required'=>'required']);select_field('badge_id','Community badge',$choices);button('Revoke','secondary','close'); ?></form></details></section>
